  ('KC', 'PELAKSANA ANALIS', '2. Cabang TIPE 1 (SME)/2.STRUKTUR CABANG.pdf', 6),
  ('D20', 'PELAKSANA AUDITOR IT', '20. BAGIAN CISO & PDP/20. STRUKTUR BAGIAN CISO & PDP.pdf', 7),
