insert into public.jobdesk (kode_dokumen, kelompok_unit, nama_jabatan, atasan_langsung, membawahi, pendidikan, pendidikan_tambahan, pangkat, pengalaman_kerja, kompetensi, fungsi, jabatan_id, file_sumber, urutan)
select v.kode_dokumen, v.kelompok_unit, v.nama_jabatan, v.atasan_langsung, v.membawahi, v.pendidikan, v.pendidikan_tambahan, v.pangkat, v.pengalaman_kerja, v.kompetensi, v.fungsi, j.id, v.file_sumber, v.urutan from (values
  ('1.0', '1. Cabang Utama', 'Pemimpin Cabang Utama', 'Direksi', array['Kepala Bagian Pemasaran', 'Kepala Bagian Operasional', 'Pemimpin Cabang Pembantu', 'Pemimpin Kantor Fungsional']::text[], 'Minimal S1', null, 'Grade 10', 'Pernah menduduki Pemimpin Cabang /Kepala Bagian Kantor Pusat/ Kepala Bagian Kantor Cabang Utama.', null, array['Berfungsi untuk mengkoordinir dan mensupervisi pelaksanaan kegiatan operasional dan pemasaran Kantor Cabang Utama didalam mencapai target pertumbuhan aktiva, laba, perkreditan dan dana serta bertanggung jawab kepada Direksi atas terlaksananya seluruh pekerjaan dan tugas-tugas pokok pengelolaan Kantor Cabang sesuai dengan batasan dan kewenangan yang diberikan oleh Direksi.']::text[], 'KCU-1.0', '1. Cabang Utama/1.0. Job Desk (Pincabut).docx', 1),
  ('1.A', '1. Cabang Utama', 'Kepala Bagian Pemasaran', 'Pemimpin Cabang Utama', array['Kepala Seksi Kredit', 'Kepala Seksi Pemasaran Dana & Jasa Elektronik']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Cabang Pembantu/ Kepala Seksi setara.', null, array['Mengkoordinir dan mensupervisi pelaksanaan pekerjaan dan tugas di bagian pemasaran kredit yang telah sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'KCU-1.A', '1. Cabang Utama/1.A. Job Desk (Kabag Pemasaran).docx', 2),
  ('1.A.1', '1. Cabang Utama', 'Kepala Seksi Kredit', 'Kepala Bagian Pemasaran', array['Relationship Manager Konsumtif', 'Relationship Manager SME', 'Relationship Manager Micro', 'Relationship Manager Collection']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Kantor Fungsional.', null, array['Berfungsi untuk mensupervisi pelaksanaan dan ikut melaksanakan kegiatan Pemasaran Produk Kredit, termasuk didalamnya memberikan rekomendasi usulan perbaikan yang bersifat operasional sesuai dengan standar operasional prosedur (SOP) yang berlaku.']::text[], 'KCU-1.A.1', '1. Cabang Utama/1.A.1. Jobdesk (Kasie Kredit Cabut).docx', 3),
  ('1.A.1.1', '1. Cabang Utama', 'Relationship Manager (RM) Konsumtif', 'Kepala Seksi Kredit', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melakukan pemetaan potensi dan pemasaran produk kredit.', 'Melaksanakan proses analisa kredit untuk memitigasi segala potensi risiko yang mungkin timbul serta kredit harus comply dengan ketentuan dan kebijakan yang berlaku dengan mengedepankan prinsip kehati-hatian (prudential banking).', 'Segmen Kredit yang menjadi ruang lingkup dan kewenangan Relationship Manager (RM) Konsumtif adalah sebagai berikut :', 'Kredit Produktif (KMG Sektor Produktif).', 'Kredit Konsumtif (Kredit Mutiguna, KPP Komersial, KPR FLPP, KKB dan produk turunannya)']::text[], 'KCU-1.A.1.1', '1. Cabang Utama/1.A.1.1. Jobdesk RM Konsumtif Ok.docx', 4),
  ('1.A.1.2', '1. Cabang Utama', 'Relationship Manager (RM) SME', 'Pemimpin Cabang Pembantu', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melakukan pemetaan potensi dan pemasaran produk kredit.', 'Melaksanakan proses analisa kredit untuk memitigasi segala potensi risiko yang mungkin timbul serta kredit harus comply dengan ketentuan dan kebijakan yang berlaku dengan mengedepankan prinsip kehati-hatian (prudential banking).', 'Segmen Kredit yang menjadi ruang lingkup dan kewenangan Relationship Manager (RM) SME Cabang/Capem adalah Kredit Produktif sebagai berikut :', 'Kredit Menengah', 'Kredit Komersial', 'Jaminan Bank']::text[], 'KCU-1.A.1.2', '1. Cabang Utama/1.A.1.2. RM SME Kantor Cabang Capem Ok.docx', 5),
  ('1.A.1.3', '1. Cabang Utama', 'Relationship Manager (RM) Micro', 'Kepala Seksi Kredit', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melakukan pemetaan potensi dan pemasaran produk kredit.', 'Melaksanakan proses analisa kredit untuk memitigasi segala potensi risiko yang mungkin timbul serta kredit harus comply dengan ketentuan dan kebijakan yang berlaku dengan mengedepankan prinsip kehati-hatian (prudential banking).', 'Segmen Kredit yang menjadi ruang lingkup dan kewenangan Relationship Manager (RM) Micro adalah sebagai berikut :', 'Kredit Produktif (Kredit Mikro).', 'Kredit Program Pemerintah (KUR, KUA & KPP)']::text[], 'KCU-1.A.1.3', '1. Cabang Utama/1.A.1.3. RM MIKRO BANKING Ok.docx', 6),
  ('1.A.1.4', '1. Cabang Utama', 'Relationship Manager (RM) Collection', 'Kepala Seksi Kredit', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melakukan pick up angsuran dan penagihan kredit, maintainance debitur existing']::text[], 'KCU-1.A.1.4', '1. Cabang Utama/1.A.1.4. Jobdesk (RM Collection).docx', 7),
  ('1.A.2', '1. Cabang Utama', 'Kepala Seksi Pemasaran Dana dan Jasa Elektronik', 'Kepala Bagian Pemasaran', array['Relationship Manager Dana & Jasa Elektronik']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Kantor Fungsional.', null, array['Berfungsi untuk mensupervisi pelaksanaan dan ikut melaksanakan kegiatan Pemasaran Dana dan Jasa Elektronik, termasuk didalamnya memberikan rekomendasi usulan perbaikan yang bersifat operasional sesuai dengan standar operasional prosedur (SOP) yang berlaku.']::text[], 'KCU-1.A.2', '1. Cabang Utama/1.A.2. Jobdesk (Kasie Pemasaran Dana dan Jasa Elektronik).docx', 8),
  ('1.A.2.1', '1. Cabang Utama', 'Relationship Manager Dana & Jasa Elektronik', 'Kepala Seksi Pemasaran Kredit, Dana & Jasa Elektronik', '{}'::text[], 'Minimal SLTA', null, null, null, null, array['Melaksanakan kegiatan Pemasaran Dana & jasa Bank kepada target market/client sesuai dengan besarnya target yang ditentukan berdasarkan Rencana Kerja dan Anggaran (Target Goal Setting) dan melakukan cross selling.']::text[], 'KCU-1.A.2.1', '1. Cabang Utama/1.A.2.1. Jobdesk Relationship Manager Dana & Jasa Elektronik).docx', 9),
  ('1.B', '1. Cabang Utama', 'Kepala Bagian Operasional', 'Pemimpin Cabang Utama', array['Kepala Seksi Pelayanan dan Jasa', 'Head Teller']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Cabang Pembantu/ Kepala Seksi setara.', null, array['Mengkoordinir dan mensupervisi Kepala Seksi Pelayanan dan Jasa dan Head Teller termasuk didalamnya memberikan rekomendasi rencana dan kebijakan pengembangan bidang operasional yang sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'KCU-1.B', '1. Cabang Utama/1.B. Job Desk (Kabag Operasional).docx', 10),
  ('1.B.1', '1. Cabang Utama', 'Kepala Seksi Pelayanan & Jasa', 'Kepala Bagian Operasional', array['Pelaksana Customer Service', 'Pelaksana Umum']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Kantor Fungsional.', null, array['Mensupervisi kegiatan layanan dan administrasi produk dan jasa perbankan kepada nasabah berdasarkan standar layanan sesuai kewenangan bidang tugasnya berdasarkan prinsip kehati-hatian di Kantor Cabang untuk mencapai target yang telah ditetapkan.']::text[], 'KCU-1.B.1', '1. Cabang Utama/1.B.1. Job Desk (Kasie Pelayanan & Jasa).docx', 11),
  ('1.B.1.1', '1. Cabang Utama', 'Customer Service', 'Kepala Seksi Pelayanan & Jasa', '{}'::text[], 'Minimal SLTA', null, null, null, null, array['Melaksanakan dan menyelesaikan tugas-tugas yang terkait dengan Pelayanan Nasabah dan antara lain pembukaan tabungan, giro, deposito, dan jasa bank lainnya sesuai dengan ketentuan standar operasional prosedur (SOP) yang berlaku.']::text[], 'KCU-1.B.1.1', '1. Cabang Utama/1.B.1.1. Jobdesk (Customer Service).docx', 12),
  ('1.B.1.2', '1. Cabang Utama', 'Pelaksana Umum', 'Kepala Seksi Pelayanan dan Jasa', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan kegiatan Rumah Tangga Kantor Bank sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'KCU-1.B.1.2', '1. Cabang Utama/1.B.1.2 Job Desk (Umum).docx', 13),
  ('1.B.2', '1. Cabang Utama', 'Head Teller', 'Kepala Bagian Operasional', array['Pelaksana Teller', 'Pelaksana Sundries', 'Pelaksana Verifikasi Transaksi']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Kantor Fungsional.', null, array['Berfungsi untuk mengkoordinir, mensupervisi dan melaksanakan kegiatan operasional Bank yang terkait dengan pembayaran dan penerimaan tunai dan non tunai dan transaksi lainnya yang dilakukan oleh Teller dan Sundries serta melakukan otorisasi transaksi sesuai kewenangan yang diberikan.']::text[], 'KCU-1.B.2', '1. Cabang Utama/1.B.2. Job Desk (Head Teller).docx', 14),
  ('1.B.2.1', '1. Cabang Utama', 'Teller', 'Head Teller', '{}'::text[], 'Minimal SLTA', null, null, null, null, array['Melaksanakan dan menyelesaikan tugas-tugas yang terkait dengan pembayaran dan penerimaan tunai sesuai dengan ketentuan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'KCU-1.B.2.1', '1. Cabang Utama/1.B.2.1  Job Desk (Teller).docx', 15),
  ('1.B.2.2', '1. Cabang Utama', 'Sundries', 'Head Teller', '{}'::text[], 'Minimal SLTA', null, null, null, null, array['Melaksanakan Penerimaan dan pembayaran non tunai antara lain kliring, pemindahbukuan, pembayaran pajak nontunai serta jasa-jasa bank lainnya termasuk penerbitan dukungan Bank dan referensi bank sesuai dengan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'KCU-1.B.2.2', '1. Cabang Utama/1.B.2.2 Job Desk (Sundries).docx', 16),
  ('1.B.2.3', '1. Cabang Utama', 'Verifikasi Transaksi', 'Head Teller', array['-']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki pemimpin kantor fungsional', null, array['Melaksanakan dan menyelesaikan tugas-tugas yang terkait dengan Verifikasi dan Pengecekan atas dokumen, slip pembukuan, kwitansi dan warkat lainnya sesuai dengan ketentuan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'KCU-1.B.2.3', '1. Cabang Utama/1.B.2.3. Job Desk (Verifikasi).docx', 17),
