  ('17.0', '17. DIVISI TREASURY', 'Kepala Divisi Treasury', 'Direktur Bisnis', array['Kepala Bagian Treasury']::text[], 'Minimal S1', null, 'Grade 10', 'Pernah menduduki Pemimpin Cabang /Kepala Bagian Kantor Pusat/ Kepala Bagian Kantor Cabang Utama.', null, array['Merumuskan strategi pengelolaan aset dan liabilitas (ALMA) untuk menjaga likuiditas, profitabilitas dan kesehatan bank.', 'Mengelola likuiditas, pendanaan, investasi surat berharga, dan transaksi treasury.', 'Memberikan rekomendasi strategi pricing dana kepada Direksi berdasarkan kondisi likuiditas dan pasar (implementasi pricing oleh Divisi Dana dan Jasa).', 'Mengelola ALCO Support dan koordinasi manajemen risiko pasar serta likuiditas.']::text[], 'D17-17.0', '17. DIVISI TREASURY/17.0. KEPALA DIVISI TREASURY.docx', 231),
  ('17.A', '17. DIVISI TREASURY', 'Kepala Bagian Treasury', 'Kepala Divisi Treasury', array['Kepala Seksi Manajemen Aset Liabilitas (ALM)', 'Kepala Seksi Dealer']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Cabang Pembantu/ Kepala Seksi setara.', null, array['Mengkoordinasikan, mengendalikan, dan mengawasi pengelolaan Treasury, ALMA, ALCO Support, Settlement, dan Money Market untuk mengoptimalkan likuiditas, profitabilitas, dan kepatuhan.']::text[], 'D17-17.A', '17. DIVISI TREASURY/17.A. KEPALA BAGIAN TREASURY.docx', 232),
  ('17.A.1', '17. DIVISI TREASURY', 'Kepala Seksi Manajemen Aset Liabilitas (ALM)', 'Kepala Bagian Treasury', array['Pelaksana ALMA', 'Pelaksana Pelaporan Treasury']::text[], 'Minimal S1', null, 'Grade 7', 'Memiliki sertifikat Dealer
Pelaksana Treasury Minimal 7 Tahun', null, array['Mengkoordinir dan mensupervisi pengelolaan struktur posisi keuangan Bank (Balance Sheet Management) guna memitigasi risiko likuiditas dan risiko suku bunga, serta memastikan akurasi penyampaian laporan regulator dan laporan manajerial untuk mendukung pengambilan keputusan strategis ALCO (Asset Liability Committee) serta Comply dengan Standar Operasional Prosedur yang berlaku.']::text[], 'D17-17.A.1', '17. DIVISI TREASURY/17.A.1. KEPALA SEKSI ALMA.docx', 233),
  ('17.A.1.1', '17. DIVISI TREASURY', 'Pelaksana ALMA', 'Kepala Seksi Manajemen Aset Liabilitas (ALM)', '{}'::text[], 'Minimal S1', null, null, null, null, array['Mengelola risiko risiko perusahaan terkait bidang treasury seperti kesenjangan likuiditas, pengelolaan risiko likuiditas, pengelolaan cash flow sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'D17-17.A.1.1', '17. DIVISI TREASURY/17.A.1.1. PELAKSANA ALMA.docx', 234),
  ('17.A.1.2', '17. DIVISI TREASURY', 'Pelaksana Pelaporan Treasury', 'Kepala Seksi ALM', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan penyusunan dan penyampaian laporan Treasury sesuai dengan target dan sasaran yang telah ditetapkan serta comply dengan Standar Operasional Prosedur (SOP) dan ketentuan yang berlaku.']::text[], 'D17-17.A.1.2', '17. DIVISI TREASURY/17.A.1.2. PELAKSANA PELAPORAN TREASURY.docx', 235),
  ('17.B.1', '17. DIVISI TREASURY', 'Kepala Seksi Dealer', 'Kepala Bagian Treasury', '{}'::text[], 'Minimal S1', null, 'Grade 7', 'Memiliki sertifikat Dealer
Menjadi Dealer minimal 7 tahun', null, array['Melaksanakan dan mengoordinasikan transaksi Treasury sesuai kewenangan yang meliputi pengelolaan likuiditas, transaksi pasar uang, transaksi surat berharga, analisis kondisi pasar, serta pengendalian risiko transaksi untuk mendukung optimalisasi profitabilitas Bank dengan tetap memperhatikan prinsip kehati-hatian, kepatuhan terhadap ketentuan regulator, dan Standar Operasional Prosedur yang berlaku.']::text[], 'D17-17.B.1', '17. DIVISI TREASURY/17.B.1. KEPALA SEKSI DEALER.docx', 236),
  ('17.B.1.1', '17. DIVISI TREASURY', 'Pelaksana Dealer', 'Kepala Seksi Dealer', '{}'::text[], 'Minimal S1', null, null, 'Memiliki Sertifikat Treasury Dealer', null, array['Melaksanakan aktivitas operasional harian pengumpulan data pasar keuangan, perhitungan kuotasi harga, serta eksekusi transaksi penempatan atau penarikan dana di pasar finansial guna mendukung pengelolaan likuiditas harian dan pencapaian target profitabilitas (trading) bank, dengan senantiasa mematuhi batasan limit risiko, prinsip kehati-hatian, serta SOP yang berlaku.']::text[], 'D17-17.B.1.1', '17. DIVISI TREASURY/17.B.1.1 PELAKSANA DEALER.docx', 237),
  ('18.0', '18. DIVISI UMUM', 'Kepala Divisi Umum', 'Direktur Umum', array['Kepala Bagian Manajemen Aset & Fasilitas', 'Kepala Bagian Pengadaan & Vendor']::text[], 'Minimal S1', null, 'Grade 10', 'Pernah menduduki Pemimpin Cabang /Kepala Bagian Kantor Pusat/ Kepala Bagian Kantor Cabang Utama.', null, array['Mengkoordinir dan mensupervisi pelaksanaan inventarisasi Aktiva tetap dan inventaris, pembelian/pengadaan Aktiva Tetap dan Inventaris, kebutuhan kantor (logistik), administrasi Aktiva Tetap dan Inventaris, pemeliharaan Aktiva Tetap dan Inventaris termasuk didalamnya pemberian rekomendasi dan rencana kerja terhadap pengembangan Sarana dan prasarana serta kegiatan lainnya dilingkungan kerja Divisi Umum.']::text[], 'D18-18.0', '18. DIVISI UMUM/18.0. Kepala Divisi Umum.docx', 238),
  ('18.A', '18. DIVISI UMUM', 'Kepala Bagian Manajemen Aset & Fasilitas', 'Kepala Divisi Umum', array['Kepala Seksi Administrasi Umum & Manajemen Aset', 'Kepala Seksi Pemeliharaan & Jaringan Kantor', 'Kepala Seksi Operasional & Logistik']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Cabang Pembantu/ Kepala Seksi setara.', null, array['Mengelola dan mengarahkan strategi pengelolaan aset, fasilitas, dan logistik Bank guna mendukung kelancaran operasional melalui optimalisasi biaya, pemeliharaan standar infrastruktur, serta kepatuhan terhadap regulasi dan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'D18-18.A', '18. DIVISI UMUM/18.A. Kepala Bagian Manajemen Aset & Fasilitas.docx', 239),
  ('18.A.1', '18. DIVISI UMUM', 'Kepala Seksi Administrasi Umum & Manajemen Aset', 'Kepala Bagian Manajemen Aset & Fasilitas', array['Pelaksana Administrasi Umum', 'Pelaksana Manajemen Aset']::text[], 'Minimal S1', null, 'Grade 7', null, null, array['Melaksanakan penatausahaan aktiva tetap dan inventaris serta mengelola administrasi pembayaran vendor guna Mengkoordinir seluruh aset bank tercatat dengan akurat dan seluruh kewajiban biaya operasional diselesaikan tepat waktu dan sesuai dengan Standar Operasional Prosedur (SOP).']::text[], 'D18-18.A.1', '18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 240),
  ('18.A.1.1', '18. DIVISI UMUM', 'Pelaksana Administrasi Umum', 'Kepala Seksi Administrasi Umum & Manajemen Aset', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan pengelolaan aktivitas umum bank yang mendukung seluruh aktivitas operasional kantor serta biaya-biaya lain yang terkait sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) di bagian Umum.']::text[], 'D18-18.A.1.1', '18. DIVISI UMUM/18.A.1.1 Job Desk (Pls.Administrasi Umum).docx', 241),
  ('18.A.1.2', '18. DIVISI UMUM', 'Pelaksana Manajemen Aset', 'Kepala Seksi Administrasi Umum & Manajemen Aset', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan pengelolaan aktivitas umum bank yang mendukung seluruh aktivitas operasional kantor serta biaya-biaya lain yang terkait sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) di bagian Umum.']::text[], 'D18-18.A.1.2', '18. DIVISI UMUM/18.A.1.2 Job Desk (Pls. Manajemen Aset).docx', 242),
  ('18.A.2', '18. DIVISI UMUM', 'Kepala Seksi Pemeliharaan dan Jaringan Kantor', 'Kepala Bagian Manajemen Aset & Fasilitas', array['Pelaksana Pemeliharaan Aset', 'Pelaksana Jaringan Kantor']::text[], 'Minimal S1', null, 'Grade 7', null, null, array['Mengkoordinir dan mensupervisi pelaksanaan pemeliharaan dan jaringan kantor sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'D18-18.A.2', '18. DIVISI UMUM/18.A.2 Job Desk (Kasie Pemeliharaan dan Jaringan Kantor).docx', 243),
  ('18.A.2.1', '18. DIVISI UMUM', 'Pelaksana Pemeliharaan Aset', 'Kepala Seksi Pemeliharaan & Jaringan Kantor', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan Pemeliharaan Aset & Inventaris Bank, sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) di bagian Umum.']::text[], 'D18-18.A.2.1', '18. DIVISI UMUM/18.A.2.1 Job Desk (Pls. Pemeliharaan aset).docx', 244),
  ('18.A.2.2', '18. DIVISI UMUM', 'Pelaksana Jaringan Kantor', 'Kepala Seksi Pemeliharaan & Jaringan Kantor', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan persiapan infrastruktur pembukaan baru dan atau perpindahan (relokasi) jaringan kantor bank, pengamanan dan kelancaran operasional, sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) di bagian Umum.']::text[], 'D18-18.A.2.2', '18. DIVISI UMUM/18.A.2.2 Job Desk (Pls. Jaringan Kantor).docx', 245),
  ('18.A.3', '18. DIVISI UMUM', 'Kepala Seksi Operasional & Logistik', 'Kepala Bagian Manajemen Aset & Fasilitas', array['Pelaksana Logistik']::text[], 'Minimal S1', null, 'Grade 7', null, null, array['Mengelola dan mengawasi seluruh aktivitas operasional logistik yang meliputi pengelolaan persediaan (inventory control), penyimpanan barang di gudang, hingga pendistribusian kebutuhan operasional ke seluruh unit kerja Bank secara tepat jumlah, tepat waktu, efisien dan comply dengan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'D18-18.A.3', '18. DIVISI UMUM/18.A.3. Kepala Seksi Operasional & Logistik.docx', 246),
  ('18.A.3.1', '18. DIVISI UMUM', 'Pelaksana Logistik', 'Kepala Seksi Operasional & Logistik', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan pengelolaan Logistik Bank dan Persediaan, sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) di bagian Umum.']::text[], 'D18-18.A.3.1', '18. DIVISI UMUM/18.A.3.1 Job Desk (Pls. Logistik).docx', 247),
  ('18.A.3.2', '18. DIVISI UMUM', 'Pelaksana Pengarsipan', 'Kepala Seksi Operasional & Logistik', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan penciptaan, penggunaan pemeliharaan dan penyusutan arsip untuk menunjang aktivitas administrasi, alat pengambil keputusan, bukti pertanggungjawaban, sumber informasi, dan wahana komunikasi.']::text[], 'D18-18.A.3.2', '18. DIVISI UMUM/18.A.3.2 Job Desk (Pls. Pengarsipan).docx', 248),
  ('18.B', '18. DIVISI UMUM', 'Kepala Bagian Pengadaan & Vendor', 'Kepala Divisi Umum', array['Kepala Seksi Rekrutmen Vendor']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Cabang Pembantu/ Kepala Seksi setara.', null, array['Mengkoordinir dan mensupervisi pelaksanaan pengadaan barang/jasa serta pengelolaan hubungan vendor sesuai dengan target yang ditetapkan, memastikan efisiensi biaya, serta menjaga kepatuhan (compliance) terhadap Standar Operasional Prosedur (SOP) dan peraturan yang berlaku.']::text[], 'D18-18.B', '18. DIVISI UMUM/18.B. Kepala Bagian Pengadaan & Vendor.docx', 249),
  ('18.B.1', '18. DIVISI UMUM', 'Kepala Seksi Manajemen Vendor', 'Kepala Bagian Pengadaan Vendor', array['Pelaksana Vendor Rekrutmen (Non IT)', 'Pelaksana Vendor Rekrutmen (IT)', 'Pelaksana Monev']::text[], 'Minimal S1', null, 'Grade 7', null, null, array['Mengkoordinir dan mensupervisi keseluruhan siklus pengadaan barang/jasa serta manajemen vendor, mulai dari perencanaan kebutuhan, proses seleksi dan negosiasi, hingga pemantauan dan evaluasi kinerja rekanan untuk mencapai efisiensi biaya, ketepatan kualitas, dan kepatuhan terhadap prosedur serta prinsip tata kelola perusahaan yang baik serta comply dengan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'D18-18.B.1', '18. DIVISI UMUM/18.B.1. Kepala Seksi Rekrutmen Vendor.docx', 250),
  ('18.B.1.1', '18. DIVISI UMUM', 'Pelaksana Rekrutmen Vendor Non IT', 'Kepala Seksi Operasional & Logistik', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan Pengadaan Aktiva Tetap dan Jasa Bank bidang Non TI, sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) di Divisi Umum']::text[], 'D18-18.B.1.1', '18. DIVISI UMUM/18.B.1.1 Job Desk (Pls. Rekrutmen Vendor Non IT).docx', 251),
  ('18.B.1.2', '18. DIVISI UMUM', 'Pelaksana Rekrutmen Vendor IT', 'Kepala Seksi Operasional & Logistik', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan Pengadaan Aktiva Tetap dan Jasa Bank bidang TI, sesuai dengan target dan sasaran yang telah ditetapkan dan comply dengan Standar Operasional Prosedur (SOP) di Divisi Umum.']::text[], 'D18-18.B.1.2', '18. DIVISI UMUM/18.B.1.2 Job Desk (Pls. Rekrutmen Vendor IT).docx', 252),
  ('18.B.1.3', '18. DIVISI UMUM', 'Pelaksana Monev', 'Kepala Seksi Operasional & Logistik', '{}'::text[], 'Minimal S1', null, null, null, null, array['Mengawasi, mengukur, dan mengevaluasi kinerja seluruh vendor (baik IT maupun Non-IT) selama masa kontrak berjalan. Fungsi ini bertindak sebagai penjamin mutu (Quality Assurance) untuk memastikan pemenuhan pengadaan sesuai waktu, memitigasi risiko operasional, serta memberikan rekomendasi strategis terkait keberlanjutan hubungan kemitraan.']::text[], 'D18-18.B.1.3', '18. DIVISI UMUM/18.B.1.3 Job Desk (Pls. Monev).docx', 253),
  ('19.0', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)', 'Kepala Satuan Kerja Audit Internal (SKAI)', 'Direktur Utama', array['Ketua Tim Auditor', 'Kepala Bagian Quality Assurance (SKAI)', 'Ketua Auditor IT']::text[], 'Minimal S1', null, 'Grade 10', 'Pernah menduduki Pemimpin Cabang /Kepala Bagian Kantor Pusat/ Kepala Bagian Kantor Cabang Utama.', null, array['Mengarahkan dan mengkoordinasikan seluruh kegiatan dalam Organisasi dan Pengelolaan Sumber Daya Satuan Audit Internal melalui sistem dan prosedur yang berlaku dalam rangka mencapai Visi Audit Intern sebagai Strategic Business Partner sehingga mendorong peningkatan dalam penerapan Sistem Pengendalian Internal, Good Corporate Governance (GCG) dan Manajemen Risiko di Bank Sultra.', 'Bertindak sebagai pendamping pemeriksa ekstern termasuk didalamnya memberikan rekomendasi, rencana dan kebijakan pengembangan pengendalian intern (internal audit) Bank.']::text[], 'D19-19.0', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)/19.0. KEPALA SATUAN KERJA AUDIT INTERNAL(SKAI).docx', 254),
  ('19.A', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)', 'Ketua Tim Auditor', 'Kepala Satuan Kerja Auditor Internal', array['Pelaksana Auditor']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Cabang Pembantu/ Kepala Seksi setara.', null, array['Mengkoordinir, melaksanakan dan mensupervisi pelaksanaan audit sesuai dengan Perencanaan audit dan sasaran yang telah ditetapkan untuk meningkatkan kecukupan dan efektivitas penerapan sistem pengendalian intern, manajemen risiko dan pelaksanaan Good Corporate Governance (GCG) serta memberikan nilai tambah dalam pencapaian tujuan Perusahaan yang telah ditetapkan']::text[], 'D19-19.A', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)/19.A. KETUA KELOMPOK AUDITOR.docx', 255),
  ('19.A.1', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)', 'Pelaksana Auditor', 'Ketua Kelompok Auditor', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan Kegiatan Audit sesuai dengan target dan sasaran yang telah ditetapkan untuk meningkatkan dan memastikan kecukupan dan efektivitas penerapan sistem pengendalian intern, manajemen risiko dan pelaksanaan Good Corporate Governance (GCG) serta memberikan nilai tambah dalam pencapaian tujuan Perusahaan yang telah ditetapkan.']::text[], 'D19-19.A.1', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)/19.A.1. PELAKSANA AUDITOR.docx', 256),
  ('19.B', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)', 'Kepala Bagian Quality Assurance', 'Kepala Satuan Kerja Audit Internal', array['Pelaksana Quality Assurance (SKAI)']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Cabang Pembantu/ Kepala Seksi setara.', null, array['Mengarahkan dan mengkoordinasikan kegiatan penyusunan Visi, Misi dan Strategi Audit Intern, Pengkajian organisasi dan kualitas Audit Intern, pengelolaan Sumber Daya, Kebijakan, Prosedure dan Saranan Penunjang Audit untuk memastikan produk jasa audit memenuhi standar yang ditetapkan termasuk memastikan kebutuhan unit kerja guna mencapai tujuan sesuai dengan target dan sasaran yang telah ditetapkan serta sesuai dengan best practices Audit Intern.']::text[], 'D19-19.B', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)/19.B. KEPALA BAGIAN QUALITY ASSURANCE.docx', 257),
  ('19.B.1', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)', 'Pelaksana Quality Assurance', 'Kepala Bagian Quality Assurance', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan dan mengevaluasi kegiatan pengkajian dan pengembangan organisasi audit intern, kualitas Audit Intern dan pengembangan SDM serta menjamin kualitas pelaksanaan audit yang dilakukan oleh auditor sesuai dengan target dan sasaran yang telah ditetapkan dan best practice audit intern.']::text[], 'D19-19.B.1', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)/19.B.1. PELAKSANA QUALITY ASSURANCE.docx', 258),
  ('19.C', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)', 'Ketua Auditor IT', 'Kepala Satuan Kerja Audit Internal', array['Pelaksana Auditor IT']::text[], 'Minimal S1', null, 'Grade 7', 'Pernah menduduki Pemimpin Cabang Pembantu/ Kepala Seksi setara.', null, array['Mengkoordinir, melaksanakan dan mensupervisi pelaksanaan audit sesuai dengan Perencanaan audit dan sasaran yang telah ditetapkan untuk meningkatkan kecukupan dan efektivitas penerapan sistem pengendalian intern, manajemen risiko dan pelaksanaan Good Corporate Governance (GCG) serta memberikan nilai tambah dalam pencapaian tujuan Perusahaan yang telah ditetapkan di Bagian Operasional Teknologi Informasi.']::text[], 'D19-19.C', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)/19.C. KETUA KELOMPOK AUDITOR IT.docx', 259),
  ('19.C.1', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)', 'Pelaksana Auditor IT', 'Ketua Kelompok Auditor IT', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan Kegiatan Audit sesuai dengan target dan sasaran yang telah ditetapkan untuk meningkatkan dan memastikan kecukupan dan efektivitas penerapan sistem pengendalian intern, manajemen risiko dan pelaksanaan Good Corporate Governance (GCG) serta memberikan nilai tambah dalam pencapaian tujuan Perusahaan yang telah ditetapkan dibidang IT.']::text[], 'D19-19.C.1', '19. SATUAN KERJA AUDIT INTERNAL (SKAI)/19.C.1. AUDITOR IT.docx', 260),
  ('20.0', '20. BAGIAN CISO & PDP', 'Kepala Bagian CISO & PDP', 'Direktur TI & Operasional', array['Kepala Seksi IT Security']::text[], 'Minimal S1 di bidang Teknologi Informasi, Sistem Informasi, Ilmu Komputer, Teknik Informatika, atau bidang lain yang relevan.', null, null, null, 'Memahami konsep cyber security, cyber resilience, dan information security governance.
Menguasai framework dan standar seperti ISO/IEC 27001, NIST Cybersecurity Framework, dan best practice keamanan informasi lainnya.
Memahami enterprise risk management dan cyber risk management.
Memahami arsitektur keamanan TI (network, system, application, data security).
Memahami regulasi terkait keamanan informasi dan perlindungan data.
Memahami prinsip three lines of defense dalam tata kelola organisasi.
Mampu menyusun strategi dan roadmap keamanan siber jangka panjang.
Memahami konsep Fraud Detection System sebagai bentuk pencegahan terjadinya tindakan kecurangan (Fraud) internal maupun eksternal.
Mampu melakukan komunikasi strategis dengan manajemen puncak dan regulator.
Memiliki sertifikasi seperti Certified Information Security Manager (CISM), Certified Information Systems Security Professional (CISSP) atau setara.', array['Melaksanakan fungsi kepemimpinan strategis dalam pengelolaan keamanan informasi dan ketahanan siber (cyber resilience), yang mencakup penetapan arah kebijakan, pengawasan implementasi IT Security, Cyber Risk Management dan pengawasan Fraud Detection System serta memastikan perlindungan aset informasi organisasi secara menyeluruh sesuai dengan risk appetite, regulasi, dan kebutuhan bisnis.']::text[], 'D20-20.0', '20. BAGIAN CISO & PDP/20.0. Job Desk Kepala Bagian - CISO & PDP.docx', 261),
  ('20.A.1', '20. BAGIAN CISO & PDP', 'Kepala Seksi IT Security', 'Kepala Bagian CISO & PDP', array['Pelaksana Security Architect', 'Pelaksana System Security', 'Pelaksana Network Security', 'Pelaksana Data Security', 'Pelaksana Application Security', 'Pelaksana Penetration Tester', 'Pelaksana SOC Monitoring', 'Pelaksana Fraud Detection System (FDS)']::text[], 'Minimal S1 di bidang Teknologi Informasi, Sistem Informasi, Ilmu Komputer, Teknik Informatika, atau bidang lain yang relevan.', null, 'Grade 7', null, 'Memahami konsep keamanan informasi dan operasional keamanan IT (IT Security Operations).
Menguasai implementasi kontrol keamanan seperIT Firewall, WAF, SIEM, IDS/IPS, EDR, Antivirus, PAM, dan teknologi keamanan lainnya.
Memahami konsep Identity and Access Management (IAM), termasuk privileged access dan role-based access control.
Memahami konsep security architecture, system security, network security, application security, dan data security.
Memahami konsep penetration testing, vulnerability assessment, dan remediation.
Memahami konsep SOC (Security Operations Center), threat monitoring, dan incident response.
Memahami prinsip three lines of defense dalam tata kelola keamanan dan risiko.
Memahami konsep Fraud Detection System sebagai bentuk pencegahan terjadinya tindakan kecurangan (Fraud) internal maupun eksternal.
Memiliki sertifikasi keamanan informasi seperti CompTIA Security+, Certified Information Systems Security Professional, atau setara.', array['Melaksanakan fungsi pengelolaan dan operasional keamanan informasi (IT Security Operations) sebagai First Line of Defense, yang mencakup implementasi, pengelolaan, monitoring, dan respons terhadap kontrol keamanan IT serta fungsi monitoring aplikasi FDS untuk melihat parameter kemungkinan terjadinya kecurangan dalam transaksi kartu debit/ATM, Qris dan mobile banking untuk melindungi aset informasi organisasi dari ancaman siber.']::text[], 'D20-20.A.1', '20. BAGIAN CISO & PDP/20.A.1 Job Desk  Kepala Seksi IT Security.docx', 262),
  ('20.A.1.1', '20. BAGIAN CISO & PDP', 'Pelaksana Security Architect', 'Kepala Seksi IT Security', '{}'::text[], 'Minimal S1 di bidang Teknologi Informasi, Sistem Informasi, Ilmu Komputer, Teknik Informatika, atau bidang lain yang relevan.', null, null, null, 'Memahami konsep security architecture dan enterprise architecture TI.
Memahami prinsip secure by design dan defense in depth.
Menguasai konsep keamanan infrastruktur TI (network, system, application, dan data security).
Memahami konsep kontrol keamanan seperti IAM, encryption, segmentation, zero trust, dan hardening.
Memahami konsep risk exposure pada desain arsitektur sistem (sebagai input teknis, bukan penilaian risiko formal).
Mampu menyusun desain teknis keamanan sistem dan infrastruktur.
Memahami prinsip three lines of defense dalam tata kelola keamanan.
Memiliki sertifikasi seperti Certified Information Systems Security Professional atau CompTIA Security+ atau setara.', array['Melaksanakan fungsi perancangan dan penguatan arsitektur keamanan TI (security architecture) sebagai bagian dari First Line of Defense, yang mencakup desain kontrol keamanan, standar arsitektur keamanan, serta dukungan teknis terhadap implementasi keamanan pada sistem, aplikasi, jaringan, dan data.']::text[], 'D20-20.A.1.1', '20. BAGIAN CISO & PDP/20.A.1.1 Job Desk (Pls Security Architect).docx', 263),
  ('20.A.1.2', '20. BAGIAN CISO & PDP', 'Pelaksana System Security', 'Kepala Seksi IT Security', '{}'::text[], 'Minimal S1 di bidang Teknologi Informasi, Sistem Informasi, Ilmu Komputer, Teknik Informatika, atau bidang lain yang relevan.', null, null, null, 'Memahami konsep system security (keamanan sistem operasi dan server).
Menguasai hardening sistem operasi (Windows, Linux, dan/atau Unix).
Memahami konsep Identity and Access Management (IAM), termasuk user provisioning, deprovisioning, dan privileged access management.
Memahami konsep patch management dan configuration management.
Memahami konsep system logging, audit trail, dan system monitoring.
Memahami dasar vulnerability management pada level sistem.
Memahami prinsip security baseline dan secure configuration.
Memahami prinsip three lines of defense dalam tata kelola keamanan.', array['Melaksanakan fungsi pengamanan sistem (system security operations) sebagai bagian dari First Line of Defense, yang mencakup pengelolaan keamanan sistem operasi, user access, hardening, patching, serta pemeliharaan konfigurasi keamanan sistem untuk menjaga integritas, kerahasiaan, dan ketersediaan sistem TI organisasi.']::text[], 'D20-20.A.1.2', '20. BAGIAN CISO & PDP/20.A.1.2 Job Desk (Pls System Security).docx', 264),
  ('20.A.1.3', '20. BAGIAN CISO & PDP', 'Pelaksana Network Security', 'Kepala Seksi IT Security', '{}'::text[], 'Minimal S1 di bidang Teknologi Informasi, Sistem Informasi, Ilmu Komputer, Teknik Informatika, atau bidang lain yang relevan.', null, null, null, 'Memahami konsep network security (keamanan jaringan komputer).
Menguasai konsep routing, switching, dan network segmentation.
Memahami implementasi firewall, IDS/IPS, VPN, dan network access control.
Memahami konsep secure network architecture (DMZ, zoning, micro-segmentation).
Memahami konsep network monitoring dan traffic analysis.
Memahami konsep secure network configuration dan hardening perangkat jaringan.
Memahami dasar vulnerability pada jaringan (network vulnerability exposure).
Memahami prinsip three lines of defense dalam tata kelola keamanan.
Memiliki sertifikasi seperti CompTIA Security+ atau Cisco Certified Network Associate Security (CCNA Security) atau setara.', array['Melaksanakan fungsi pengamanan jaringan (network security operations) sebagai bagian dari First Line of Defense, yang mencakup pengelolaan keamanan infrastruktur jaringan, konfigurasi perangkat keamanan jaringan, monitoring traffic, serta implementasi kontrol keamanan jaringan untuk melindungi komunikasi data organisasi dari ancaman siber.']::text[], 'D20-20.A.1.3', '20. BAGIAN CISO & PDP/20.A.1.3 Job Desk (Pls Network Security).docx', 265),
  ('20.A.1.4', '20. BAGIAN CISO & PDP', 'Pelaksana Data Security', 'Kepala Seksi IT Security', '{}'::text[], 'Minimal S1 di bidang Teknologi Informasi, Sistem Informasi, Ilmu Komputer, Teknik Informatika, atau bidang lain yang relevan.', null, null, null, 'Memahami konsep data security (keamanan data dan informasi).
Memahami konsep data classification (public, internal, confidential, restricted).
Menguasai konsep data protection seperti encryption at-rest dan in-transit.
Memahami konsep data loss prevention (DLP).
Memahami konsep data access control dan data authorization.
Memahami konsep data lifecycle management (storage, usage, retention, deletion).
Memahami konsep backup, restore, dan data recovery.
Memahami dasar data privacy dan perlindungan data sensitif.
Memahami prinsip three lines of defense dalam tata kelola keamanan.', array['Melaksanakan fungsi pengamanan data (data security operations) sebagai bagian dari First Line of Defense, yang mencakup perlindungan, pengendalian akses, klasifikasi, enkripsi, serta pengelolaan siklus hidup data untuk memastikan kerahasiaan, integritas, dan ketersediaan data organisasi.']::text[], 'D20-20.A.1.4', '20. BAGIAN CISO & PDP/20.A.1.4 Job Desk (Pls Data Security).docx', 266),
  ('20.A.1.5', '20. BAGIAN CISO & PDP', 'Pelaksana Application Security', 'Kepala Seksi IT Security', '{}'::text[], 'Minimal S1 di bidang Teknologi Informasi, Sistem Informasi, Ilmu Komputer, Teknik Informatika, atau bidang lain yang relevan.', null, null, null, 'Memahami konsep application security (keamanan aplikasi).
Memahami konsep secure software development lifecycle (SSDLC).
Menguasai dasar secure coding dan common vulnerabilities (OWASP Top 10).
Memahami konsep API security dan web application security.
Memahami konsep authentication, authorization, dan session management pada aplikasi.
Memahami konsep vulnerability assessment pada aplikasi.
Memahami konsep application testing (SAST, DAST, basic penetration testing aplikasi).
Memahami konsep secure configuration pada aplikasi (bukan infrastruktur).
Memahami prinsip three lines of defense dalam tata kelola keamanan.
Memiliki sertifikasi seperti Certified Secure Software Lifecycle Professional (CSSLP) atau CompTIA Security+ menjadi nilai tambah.', array['Melaksanakan fungsi pengamanan aplikasi (application security operations) sebagai bagian dari First Line of Defense, yang mencakup pengujian keamanan aplikasi, analisis kerentanan aplikasi, implementasi kontrol keamanan aplikasi, serta dukungan perbaikan keamanan aplikasi untuk memastikan aplikasi organisasi aman dari ancaman siber.']::text[], 'D20-20.A.1.5', '20. BAGIAN CISO & PDP/20.A.1.5 Job Desk (Pls Application Security).docx', 267),
  ('20.A.1.6', '20. BAGIAN CISO & PDP', 'Pelaksana Penetration Tester', 'Kepala Seksi IT Security', '{}'::text[], 'Minimal S1 di bidang Teknologi Informasi, Sistem Informasi, Ilmu Komputer, Teknik Informatika, atau bidang lain yang relevan.', null, null, null, 'Memahami konsep penetration testing dan ethical hacking.
Menguasai metodologi penetration testing (reconnaissance, scanning, exploitation, post-exploitation).
Memahami kerentanan umum pada aplikasi, sistem, dan jaringan seperti OWASP Top 10.
Memahami teknik eksploitasi dasar pada web, mobile, network, dan system.
Memahami tools penetration testing dan vulnerability scanning.
Memahami konsep vulnerability validation dan exploit verification.
Memahami dasar secure configuration dan security control dalam konteks pengujian.
Memahami prinsip three lines of defense dalam tata kelola keamanan.
Memiliki sertifikasi seperti Offensive Security Certified Professional (OSCP) atau Certified Ethical Hacker (CEH).', array['Melaksanakan fungsi pengujian keamanan (penetration testing) sebagai bagian dari First Line of Defense, yang mencakup simulasi serangan terhadap sistem, aplikasi, dan jaringan, baik secara internal maupun melalui pihak ketiga, untuk mengidentifikasi celah keamanan secara proaktif serta memastikan hasil pengujian ditindaklanjuti secara efektif guna meningkatkan ketahanan keamanan TI organisasi.']::text[], 'D20-20.A.1.6', '20. BAGIAN CISO & PDP/20.A.1.6 Job Desk (Pls Penetration Tester).docx', 268),
  ('20.A.1.7', '20. BAGIAN CISO & PDP', 'Pelaksana SOC Monitoring', 'Kepala Seksi IT Security', '{}'::text[], 'Minimal S1 di bidang Teknologi Informasi, Sistem Informasi, Ilmu Komputer, Teknik Informatika, atau bidang lain yang relevan.', null, null, null, 'Memahami konsep Security Operations Center (SOC) dan fungsi monitoring keamanan.
Memahami konsep security monitoring, alerting, dan event correlation.
Memahami dasar SIEM (Security Information and Event Management).
Memahami konsep log management dan log analysis dari berbagai sumber (network, system, application, database).
Memahami konsep incident detection dan security event classification.
Memahami dasar threat intelligence dan Indicator of Compromise (IoC).
Memahami konsep basic incident response workflow (deteksi, eskalasi, dokumentasi).
Memahami prinsip three lines of defense dalam tata kelola keamanan.
Certified SOC Analyst (CSA) atau setara.', array['Melaksanakan fungsi monitoring, deteksi, dan analisis awal insiden keamanan siber (security event monitoring) sebagai bagian dari First Line of Defense, yang mencakup pengawasan aktivitas keamanan dari berbagai sistem, identifikasi anomali, serta eskalasi awal insiden keamanan kepada pihak terkait untuk penanganan lebih lanjut.']::text[], 'D20-20.A.1.7', '20. BAGIAN CISO & PDP/20.A.1.7 Job Desk (Pls SOC Monitoring).docx', 269),
  ('20.A.1.8', '20. BAGIAN CISO & PDP', 'Pelaksana Fraud Detection System (FDS)', 'Kepala Seksi IT Security', '{}'::text[], 'Minimal S1', null, null, null, null, array['Melaksanakan fungsi monitoring pada aplikasi FDS untuk melihat parameter kemungkinan terjadinya penipuan atau kecurangan dalam transaksi Kartu Debit/ATM, QRIS dan Mobile Banking sesuai yang ditetapkan dalam pedoman yang berlaku.']::text[], 'D20-20.A.1.8', '20. BAGIAN CISO & PDP/20.A.1.8 Job Desk Pelaksana Fraud Detection System.docx', 270),
  ('21.0', '21. KANTOR FUNGSIONAL', 'Pemimpin Kantor Fungsional', 'Pemimpin Cabang Utama / Pemimpin Cabang / Pemimpin Capem', array['Teller', 'Customer Service/Pelaksana Sundries', 'Relationship Manager Dana & Jasa Elektronik']::text[], 'Minimal S1
Grade 6', null, null, 'Mempunyai pengalaman sebagai Pelaksana minimal selama 3 tahun.', null, array['Berfungsi untuk mengkoordinir dan mensupervisi pelaksanaan kegiatan operasional dan pemasaran Kantor Fungsional, didalam mencapai target pertumbuhan dana dan bertanggungjawab kepada atasan langsung atas terlaksananya seluruh pekerjaan dan tugas-tugas pokok pengelolaan Kantor Fungsional dan melakukan Otorisasi, Verifikasi dan Pengecekan atas dokumen, slip pembukuan, kwitansi dan warkat lainnya sesuai dengan batasan dan kewenangan yang diberikan oleh Direksi, termasuk memberikan rekomendasi rencana dan kebijakan pengembangan Kantor Fungsional.']::text[], 'KF-21.0', '21. KANTOR FUNGSIONAL/21.0. Job Desk (Pemimpin Kantor Fungsional.docx', 271),
  ('21.A.1', '21. KANTOR FUNGSIONAL', 'Customer Service', 'Pemimpin Kantor Fungsional', '{}'::text[], 'Minimal SLTA', null, null, null, null, array['Melaksanakan dan menyelesaikan tugas-tugas yang terkait dengan Pelayanan Nasabah antara lain pembukaan tabungan, giro, deposito, dan jasa bank lainnya sesuai dengan ketentuan standar operasional prosedur (SOP) yang berlaku.']::text[], 'KF-21.A.1', '21. KANTOR FUNGSIONAL/21.A.1 Job Desk (Customer Service).docx', 272),
  ('21.A.2', '21. KANTOR FUNGSIONAL', 'Teller', 'Pemimpin Kantor Fungsional', '{}'::text[], 'Minimal SLTA', null, null, null, null, array['Melaksanakan dan menyelesaikan tugas-tugas yang terkait dengan pembayaran dan penerimaan tunai/non tunai, kliring, sesuai dengan ketentuan Standar Operasional Prosedur (SOP) yang berlaku.']::text[], 'KF-21.A.2', '21. KANTOR FUNGSIONAL/21.A.2 Job Desk (Teller).docx', 273),
  ('21.A.3', '21. KANTOR FUNGSIONAL', 'Relationship Manager Dana & Jasa Elektronik', 'Kepala Kantor Fungsional', '{}'::text[], 'Minimal SLTA', null, null, null, null, array['Melaksanakan kegiatan Pemasaran Dana & jasa Bank kepada target market/client sesuai dengan besarnya target yang ditentukan berdasarkan Rencana Kerja dan Anggaran (Target Goal Setting) dan melakukan cross selling.']::text[], 'KF-21.A.3', '21. KANTOR FUNGSIONAL/21.A.3 Jobdesk (AO Pemasaran Dana & Jasa Elektronik).docx', 274),
  ('21.A.3', '21. KANTOR FUNGSIONAL', 'Relationship Manager Dana & Jasa Elektronik', 'Kepala Kantor Fungsional', '{}'::text[], 'Minimal SLTA', null, null, null, null, array['Melaksanakan kegiatan Pemasaran Dana & jasa Bank kepada target market/client sesuai dengan besarnya target yang ditentukan berdasarkan Rencana Kerja dan Anggaran (Target Goal Setting) dan melakukan cross selling.']::text[], 'KF-21.A.3', '21. KANTOR FUNGSIONAL/21.A.3 Jobdesk (Relationship Manager Dana & Jasa Elektronik).docx', 275)
) v(kode_dokumen, kelompok_unit, nama_jabatan, atasan_langsung, membawahi, pendidikan, pendidikan_tambahan, pangkat, pengalaman_kerja, kompetensi, fungsi, jabatan, file_sumber, urutan)
left join public.jabatan j on j.kode = v.jabatan;

insert into public.jobdesk_tugas (jobdesk_id, urutan, kategori, deskripsi)
select d.id, v.urutan, v.kategori, v.deskripsi from (values
  ('1. Cabang Utama/1.0. Job Desk (Pincabut).docx', 1, 'Perencanaan', 'Menyusun dan mendiskusikan target-target yang akan ditetapkan dalam Rencana Kerja dan Anggaran (RKA) dan Rencana Bisnis Bank sesuai dengan kapasitas yang dimiliki dan juga mempertimbangkan share terhadap bank lain.'),
