update public.jabatan j set ikhtisar_jabatan = array_to_string(d.fungsi, E'\n'),
  uraian_tugas = array(select t.deskripsi from public.jobdesk_tugas t where t.jobdesk_id = d.id order by t.urutan)
from (select distinct on (jabatan_id) * from public.jobdesk where jabatan_id is not null order by jabatan_id, urutan) d
where j.id = d.jabatan_id;

