update public.jobdesk_tugas t set alasan_tanpa_kode = v.alasan, saran_kompetensi = v.saran,
  catatan_tanpa_kode = v.catatan, tanpa_kompetensi = v.alasan = 'celah' from (values
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 4, 'celah', '{}'::text[], 'Penjadwalan pembinaan kearsipan adalah manajemen kearsipan (records management) yang belum ada padanannya di kamus.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 5, 'celah', '{}'::text[], 'Perencanaan sarana prasarana kearsipan standar menuntut keahlian kearsipan yang tidak tercakup kompetensi kamus mana pun.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 6, 'celah', '{}'::text[], 'Program digitalisasi arsip menuntut kompetensi manajemen kearsipan/arsip elektronik yang belum tersedia di kamus.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 7, 'kepemimpinan', '{}'::text[], 'Penetapan dan distribusi target kepada bawahan adalah fungsi manajerial (kepemimpinan).'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 12, 'terlewat', array['CGA-11']::text[], 'Pemindahan arsip inaktif ke gudang arsip pusat adalah ekspedisi dan logistik dokumen yang diukur CGA-11.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 13, 'terlewat', array['CGA-11']::text[], 'Database indeks arsip agar dokumen terlacak sejalan dengan pengelolaan dokumen terstruktur dan terlacak pada CGA-11.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 14, 'celah', '{}'::text[], 'Verifikasi pemusnahan arsip berdasarkan Jadwal Retensi Arsip adalah ranah kearsipan yang belum ada di kamus.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 15, 'umum', '{}'::text[], 'Pemutakhiran pengetahuan peraturan secara berkala adalah kewajiban umum, dicakup Kompetensi Inti.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 16, 'umum', '{}'::text[], 'Tindak lanjut temuan audit atas unit sendiri adalah kewajiban umum kepatuhan, dicakup Kompetensi Inti.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 17, 'kepemimpinan', '{}'::text[], 'Memberi arahan pelaksanaan tugas kepada bawahan adalah fungsi supervisi (kepemimpinan).'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 21, 'celah', '{}'::text[], 'Bimtek tata cara pengarsipan menuntut keahlian kearsipan; kamus tidak memiliki kompetensi manajemen arsip.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 22, 'kepemimpinan', '{}'::text[], 'Memotivasi dan membina bawahan adalah fungsi kepemimpinan.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 23, 'umum', '{}'::text[], 'Penerapan budaya kerja STAR adalah aspek perilaku yang dicakup Kompetensi Inti.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 24, 'umum', '{}'::text[], 'Tugas lain dari atasan bersifat umum dan tidak menuntut kompetensi teknis tertentu.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 25, 'kepemimpinan', '{}'::text[], 'Memantau dan bertanggung jawab atas hasil kerja bawahan adalah fungsi supervisi.'),
  ('18. DIVISI UMUM/18.A.1. Kepala Seksi Manajemen Aset & Administrasi Umum.docx', 30, 'kepemimpinan', '{}'::text[], 'Pengawasan atas pekerjaan bawahan adalah fungsi supervisi (kepemimpinan).'),
